import { defineStyles } from '@/utils/defineStyles'
import { colors, useTheme } from '@/theme'
import { ChevronRight, ExternalLink } from 'lucide-react-native'
import { Text, TouchableOpacity, View } from 'react-native'
import { Switch } from './Switch'

interface SettingsItemProps {
	title: string
	subtitle?: string
	onPress?: () => void
	type?: 'button' | 'link' | 'toggle' | 'none'
	appearance?: 'primary' | 'secondary' | 'destructive'
	toggleValue?: boolean
	onToggleChange?: (value: boolean) => void
}

export const SettingsItem = ({
	title,
	subtitle,
	onPress,
	type = 'button',
	appearance = 'secondary',
	toggleValue,
	onToggleChange
}: SettingsItemProps) => {
	const { theme } = useTheme()

	const Icon = type === 'link' ? ExternalLink : ChevronRight
	const Container = type !== 'toggle' && onPress ? TouchableOpacity : View
	const textColor =
		appearance === 'destructive'
			? colors[theme].red[400]
			: appearance === 'primary'
			? colors[theme].gray[900]
			: colors[theme].gray[400]

	return (
		<Container onPress={onPress} style={styles.container}>
			<View style={styles.textContainer}>
				<Text style={[styles.title, { color: textColor }]}>{title}</Text>
				{subtitle && (
					<Text style={[styles.title, { color: colors[theme].gray[400] }]}>
						{subtitle}
					</Text>
				)}
			</View>
			{type === 'toggle' && toggleValue !== undefined && onToggleChange ? (
				<Switch
					value={toggleValue}
					onChange={onToggleChange}
					trackColors={{
						on: colors[theme].gray[900],
						off: colors[theme].gray[300]
					}}
				/>
			) : type !== 'none' ? (
				<Icon
					size={22}
					color={
						appearance === 'destructive'
							? colors[theme].red[400]
							: colors[theme].gray[400]
					}
					style={Icon === ChevronRight ? styles.chevronIconStyle : undefined}
				/>
			) : null}
		</Container>
	)
}

const styles = defineStyles({
	container: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		paddingVertical: 8
	},
	textContainer: {
		flex: 1,
		gap: 4
	},
	title: {
		fontSize: 16,
		fontWeight: '500'
	},
	chevronIconStyle: {
		transform: [{ translateX: 4 }]
	}
})
